import csv; import json; from datetime import datetime
with open(CATALOG_CSV, 'r') as f, open(VALUE_CSV, 'r') as v: 
    catalog = list(csv.DictReader(f)); values = list(csv.DictReader(v))
hours = {row['timeseries_id']: row for row in catalog if row['point_class'] == 'sensor' and row['building_id'] == 'id_of_the_building' and row['quantity_kind'] == 'electric_power'}
matches = {'Core_bottom': 0, 'Perimeter_bot_ZN_4': 0, 'Perimeter_top_ZN_1': 0}
for row in values: 
    if row['timeseries_id'] in hours and row['timestamp'] == '2018-10-12': 
        zone = catalog[[r['point_uri'] for r in catalog if r['timeseries_id'] == row['timeseries_id']][0]]['point_class'] 
        matches[zone] = matches[zone] + int(row['value']) 
most = max(matches, key=matches.get)
print(json.dumps({'entity': most}))
